from pathlib import Path
import json,base64,io,gzip,hashlib
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
root=Path(__file__).resolve().parent
old=json.loads((root/'baseline/results.json').read_text() if (root/'baseline/results.json').exists() else gzip.decompress((root/'baseline/results.json.gz').read_bytes()))
new=json.loads((root/'phase1-results.json').read_text() if (root/'phase1-results.json').exists() else gzip.decompress((root/'phase1-results.json.gz').read_bytes()))
assert len(old['results'])==len(new['results'])==1500
keys=['cautious','normal','aggressive','optimized','bad','ruin'];labels=['Vorsichtig','Normal','Aggressiv','Optimiert*','5 Fehlentscheidungen','30 Fehlentscheidungen']
summary=[];table='';risk=''
for k,label in zip(keys,labels):
 a=[r for r in old['results'] if r['strategy']==k];b=[r for r in new['results'] if r['strategy']==k];assert [r['seed'] for r in a]==[r['seed'] for r in b]
 def stat(g):
  e=[r['eld']['day'] for r in g if r['eld']]
  return dict(median=float(np.median([r['wealth'] for r in g])),p10=float(np.percentile([r['wealth'] for r in g],10)),p90=float(np.percentile([r['wealth'] for r in g],90)),elderman=len(e),medianDays=float(np.median(e)) if e else None,insolvent=sum(r['insolvent'] for r in g),stranded=sum(r['stranded'] for r in g),recovered=sum(r['recovered'] for r in g),fees=float(np.median([r['metrics']['fees'] for r in g])),repair=float(np.median([r['metrics']['repairs'] for r in g])),interest=float(np.median([r['metrics']['interest'] for r in g])),pirates=float(np.median([r['metrics']['pirates'] for r in g])),profit=float(np.median([r['metrics']['realisedProfit'] for r in g])))
 x,y=stat(a),stat(b);summary.append({'strategy':k,'label':label,'before':x,'after':y,'wealthChangePct':100*(y['median']/x['median']-1)})
 def f(v):return '–' if v is None else f'{v:,.0f}'.replace(',','.')
 table+=f'<tr><th>{label}</th><td>{f(x["median"])}</td><td>{f(y["median"])}</td><td>{100*(y["median"]/x["median"]-1):+.1f}%</td><td>{x["elderman"]} → {y["elderman"]}</td><td>{f(x["medianDays"])} → {f(y["medianDays"])}</td></tr>'
 risk+=f'<tr><th>{label}</th><td>{x["stranded"]} → {y["stranded"]}</td><td>{x["insolvent"]} → {y["insolvent"]}</td><td>{x["recovered"]} → {y["recovered"]}</td><td>{f(x["pirates"])} → {f(y["pirates"])}</td><td>{f(x["interest"])} → {f(y["interest"])}</td></tr>'
plt.rcParams.update({'font.family':'DejaVu Sans','axes.spines.top':False,'axes.spines.right':False,'figure.facecolor':'#faf6ed','axes.facecolor':'#faf6ed'})
fig,axs=plt.subplots(1,2,figsize=(12,4.6));ix=np.arange(6)
for a,col,field,title in [(axs[0],'#8b654a','median','Endvermögen, Median'),(axs[1],'#427d80','medianDays','Spieltage bis Eldermann, Median')]:
 a.bar(ix-.18,[x['before'][field] or 0 for x in summary],.36,color='#b8ab92',label='Vorher');a.bar(ix+.18,[x['after'][field] or 0 for x in summary],.36,color=col,label='Phase 1');a.set_xticks(ix,labels,rotation=25,ha='right');a.set_title(title);a.legend();a.set_ylabel('Gold (logarithmisch)' if field=='median' else 'Spieltage, nur Erfolge')
 if field=='median':a.set_yscale('log')
buf=io.BytesIO();fig.savefig(buf,format='png',dpi=140,bbox_inches='tight');plt.close(fig);img=base64.b64encode(buf.getvalue()).decode()
invalid=sum(any(r['metrics'][k] for k in ['negativeGold','invalidCargo','invalidPrice']) for r in new['results'])
text=f'''<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hansefürst 0.4.2 – Phase 1</title><style>body{{max-width:1100px;margin:auto;padding:26px;font:17px/1.6 system-ui;background:#faf6ed;color:#263b3b}}h1,h2{{font-family:Georgia}}table{{border-collapse:collapse;width:100%;font-size:14px}}td,th{{border-bottom:1px solid #c8bda9;padding:9px;text-align:right}}th:first-child{{text-align:left}}.scroll{{overflow:auto}}img{{width:100%;height:auto}}code{{overflow-wrap:anywhere}}.note{{background:#eee3cc;padding:16px}}</style><h1>Hansefürst 0.4.2: Phase 1</h1><p>Vier gezielte Korrekturen · 1.500 neue Verläufe · Vergleich mit 1.500 bisherigen Verläufen</p><h2>Was wurde geändert?</h2><ol><li><b>Reiseereignisse:</b> Die Vorschau würfelt nichts mehr aus. Erst beim verbindlichen Weitersegeln wird das Ereignis ermittelt. Schließen, erneutes Planen oder Neuladen vor der Abfahrt bringen keinen Informationsvorteil. Wiederholte Ankunft bleibt gesperrt.</li><li><b>Aufträge:</b> Käufe speichern den Herkunftshafen je Warenmenge. Verkäufe verbrauchen Mengen nach FIFO; nur Ware aus einer anderen Stadt zählt für die Lieferung. Lokaler Sofortkauf/-verkauf, Mischladungen und Piratenverluste wurden getestet. Bestehende Altbestände bleiben vollständig handelbar; ohne belegte Herkunft gelten sie nicht als Auftragslieferung.</li><li><b>Zinsen:</b> Taggenaue effektive Verzinsung mit Faktoren 1,02^(1/360) und 1,06^(1/360). Nach 360 Tagen gelten weiterhin genau 2 % bzw. 6 %, unabhängig vom Kalenderdatum. Keine tägliche Ganzzahlrundung, kein zusätzlicher Jahreswechselzins. Bruchteile lassen sich vollständig abheben oder tilgen. Keine rückwirkende Zinsbelastung alter Salden.</li><li><b>Vermögen:</b> Ladung zählt für Kredit und Karriere zum gewichteten Einstand. Bei unbekannten Altkosten wird bei Übernahme einmalig min(Basispreis, Hafenpreis) als Buchwert eingefroren; der tatsächliche Einkaufspreis bleibt unbekannt. Gewinne werden beim Verkauf realisiert. Gold, Eigentum und erreichte Ränge werden nicht rückwirkend gekürzt.</li></ol><p class="note"><b>Keine weiteren Balanceänderungen:</b> Preise, Warenmengen, Rangschwellen, Auftragsprämien, Hafengebühren, Reparaturtarife und Piratenwahrscheinlichkeiten blieben unverändert. Die neue Herkunftsprüfung und Bewertung sind die ausdrücklich gewünschten Regelkorrekturen.</p><h2>Tests und Methode</h2><p>18 neue Phase-1-Regressionen, 19 bestehende Spieltests, 14 aktualisierte Mechanikprüfungen sowie Telemetrie- und Teilen-Prüfungen bestehen. Ein Seed-Lauf vor den Änderungen entsprach den gespeicherten Baseline-Daten exakt. Die alte HTML-Datei und Strategien sind separat archiviert.</p><p>Erneut sechs Strategien mit je 250 Seeds (Mulberry32, 10001–10250), maximal 1.440 Spieltage bzw. 800 Entscheidungszyklen; letzte Reise darf die Tagesgrenze überschreiten. Die Politik der Bots blieb identisch. Nur die Messung von Ereignissen wurde an den neuen Zeitpunkt und die Messung der Zinsen an tägliche Buchungen angepasst. Gleiche Seeds bedeuten wegen abweichender Handlungsfolgen nicht durchgehend identische spätere Zufallsereignisse.</p><p><b>Vergleichsgrenze:</b> Normaler und optimierter Bot versuchen weiterhin die bisherige lokale Auftragsstrategie. Diese liefert jetzt keine Prämie mehr. Die Ergebnisse messen deshalb den Schutz gegen die bisherige Strategie; sie zeigen nicht die beste erreichbare Rendite mit neu geplanten legitimen Auftragsrouten. Optimiert* besitzt weiterhin perfekte Kenntnis aktueller Marktpreise. Die bewusst schlechte Strategie kennt die Preise ebenfalls, um schädliche Geschäfte gezielt auszuwählen.</p><h2>Vermögen und politischer Aufstieg</h2><div class="scroll"><table><tr><th>Strategie</th><th>Median vorher</th><th>Median nachher</th><th>Änderung</th><th>Eldermann /250</th><th>Median Spieltage vorher → nachher</th></tr>{table}</table></div><p>Endvermögen nach dem jeweiligen Horizont, nach Schlussverkauf der Ladung; Erfolge laufen anschließend weiter. Spieltage bis Eldermann beziehen sich nur auf erfolgreiche Läufe. Ausfälle werden nicht als kurze Aufstiegsdauer gewertet. Median bei sehr wenigen Erfolgen ist wenig belastbar.</p><img src="data:image/png;base64,{img}" alt="Vergleich von Medianvermögen und Spieltagen bis Eldermann vor und nach Phase 1"><h2>Risiken und Erholung</h2><div class="scroll"><table><tr><th>Strategie</th><th>Stillstand /250</th><th>Nettovermögen ≤0 /250</th><th>Erholung /250</th><th>Median Piratenverluste (Ereignisse)</th><th>Median Kreditzinsen</th></tr>{risk}</table></div><p>Stillstand bedeutet: Die nächste Reise ist nach den vorgesehenen Verkaufs-, Abhebe- und Kreditversuchen nicht finanzierbar. Dies ist keine juristische Insolvenzdefinition. Erholung nach Fehlentscheidungen bedeutet Rückkehr über das anfängliche Schätzvermögen von 9.960 Gold. Kürzere Stressläufe sind bei Ereigniszahlen und Kosten nicht direkt mit vollständigen Verläufen vergleichbar.</p><p>In {invalid} von 1.500 neuen Läufen wurden negatives/nicht endliches Gold, überschrittene Ladekapazität, negative Ladung oder numerisch ungültige Preise erkannt. Wirtschaftlich überhöhte, aber gültige Preise sind davon nicht erfasst. Spieltage, Entscheidungszyklen und Simulator-Rechenzeit sind <b>keine menschlichen Spielstunden</b>.</p><h2>Welche Probleme bestehen weiterhin?</h2><ul><li>Marktpreise reagieren weiterhin nicht auf eigene Handelsmengen und haben keine feste Obergrenze oder Rückkehr zu städtischen Normalpreisen.</li><li>Liquiditätsstillstand trotz positivem Schiffswert bleibt möglich; ein Schiffverkauf oder neue Nothilfe wurde nicht ergänzt.</li><li>Piratenverluste skalieren weiterhin schwach mit Flottengröße; Reparaturpreise bleiben unabhängig vom Schiffstyp.</li><li>Buchwerte bekannter Ware erkennen Gewinne erst beim Verkauf, berücksichtigen aber keine zwischenzeitlichen Marktwertverluste. Die Bewertung ist kein Liquidationswert.</li><li>Herkunft und FIFO reichen für diese Auftragsprüfung aus, ersetzen aber kein vollständiges Losbuch mit individuellen Einkaufskosten.</li><li>Lokale Spielstände bleiben editierbar. Schutz vor manipulierten Dateien oder bewusst wiederhergestellten alten Sicherungen ist kein Ziel dieser Offline-Korrekturen.</li><li>Safari und echte iPhones/iPads sind weiterhin praktisch zu testen.</li></ul><h2>Nachvollziehbarkeit</h2><p>Baseline-Hash: <code>{old['sourceSHA256']}</code><br>Neue Spieldatei: <code>{new['sourceSHA256']}</code></p><p><code>node tests/phase1.cjs</code> prüft die Korrekturen. <code>SIM_OUTPUT=phase1-results.json node tests/simulation/run.cjs</code> reproduziert die neue Simulation. <code>python tests/simulation/compare-phase1.py</code> erzeugt diesen Vergleich (NumPy, Matplotlib). Daten stehen unter <code>tests/simulation/baseline/results.json.gz</code> und <code>tests/simulation/phase1-results.json.gz</code>; summary-phase1.json enthält die Kennzahlen. Rohdaten sind reine Simulationen, keine echten Spielerdaten.</p><p><a href="testbericht-vor-phase1.html">Bisheriger Bericht</a> · <a href="./">Zum Spiel</a></p></html>'''
(root/'summary-phase1.json').write_text(json.dumps(summary,indent=2));(root/'phase1-report.html').write_text(text)
dist=(root/'../../dist').resolve();(dist/'testbericht.html').write_text(text);(dist/'testbericht-vor-phase1.html').write_text((root/'baseline/report.html').read_text())
print(json.dumps(summary,indent=2))
